package com.example.urlshortener.model;import jakarta.persistence.*;import lombok.AllArgsConstructor;import lombok.Builder;import lombok.Data;import lombok.NoArgsConstructor;import org.hibernate.annotations.CreationTimestamp;import org.hibernate.annotations.UpdateTimestamp;import java.time.LocalDateTime;@Entity@Table(name = "urls")@Data@NoArgsConstructor@AllArgsConstructor@Builderpublic class Url {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    @Column(name = "original_url", nullable = false, length = 2048)    private String originalUrl;    @Column(name = "short_code", unique = true, nullable = false, length = 10)    private String shortCode;    @CreationTimestamp    @Column(name = "created_at", nullable = false, updatable = false)    private LocalDateTime createdAt;    @Column(name = "expires_at")    private LocalDateTime expiresAt;    @Column(name = "clicks", nullable = false)    private Integer clicks = 0;    @UpdateTimestamp    @Column(name = "updated_at", nullable = false)    private LocalDateTime updatedAt;}